head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (dlt_pData 포함)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined' && scwin.target1) {
        scwin.target1.remove();
    }

    // 조건 설정 (디자인 시 설정할 컴포넌트 ID)
    let cID = scwin.gVar["cID"];

    // pivot 은 빈 id 로 직접 dynamicCreate 시 내부 after-hook 오류가 발생하므로
    // 공통 생성 함수(createBasicPivot)로 생성한다.
    //  - cID 가 빈값이면 createBasicPivot 내부에서 'target1' 로 고정된다.
    //  - createBasicPivot 는 생성된 pivot 을 반환하므로 scwin.target1 로 캡처한다.
    scwin.target1 = await $c.gcm.createBasicPivot('', '', cID);
}
